namespace NetEvolve.Schemas.XPath.Tests.Unit.Casting.Other;

/// <summary>
/// The selection of the QT3 test sets <c>prod-CastExpr</c> and <c>prod-CastableExpr</c> for the types that the casting table gained with the
/// date, time, Gregorian, duration, binary, URI, and QName rows: the XPath 2.0 cases (the dependency rule of the QT3 selector of the integration
/// tests) that name at least one of these types, whose expression consists only of literals, the constructor functions of the primitive types,
/// <c>cast as</c>, <c>castable as</c>, and the value comparisons <c>eq</c> and <c>ne</c>, so that every case runs through the lowerings of the
/// production code. The cases are taken from the pinned commit of the suite (tests/conformance/suites/qt3.json); the expectation is a
/// tab-separated list of alternatives: <c>T</c> or <c>F</c> for a boolean, <c>S:</c> and <c>N:</c> for a string value (<c>N:</c> with normalized
/// space), <c>P:</c> for a string value that starts with a prefix, <c>E:</c> for a value equal to an expression, <c>R:</c> for a numeric value between a
/// lower and an upper bound, and <c>X:</c> for an error code.
/// </summary>
/// <remarks>
/// <para>
/// A case whose assertion is <c>not(E)</c> is listed as <c>E</c> with the opposite boolean, because the function <c>fn:not</c> belongs to the
/// boolean function group that has not landed; the value of the case is the same. Cases of these two sets that name a type of the derived types
/// (<c>xs:int</c>, <c>xs:token</c>, and the like) belong to XP-23 (#299).
/// </para>
/// <para>
/// Limitation: the QT3 runner of the integration tests still has no evaluator behind it (#295), so these cases run through the lowerings of
/// <see cref="Core.CastFixture"/> and not through the runner; the end-to-end run stays open until #295, as for the seven types (#265).
/// <see cref="Excluded"/> lists every case of the same shape that is left out, with the reason: a comparison of dates, times, durations,
/// Gregorian values, binary values, or QNames needs the operators of XP-26 (#300); a constructor function of a QName with a prefix needs the
/// static context of the call, which the lowering of a function call has yet to hand over (#644); the lexical check of <c>xs:anyURI</c> is lax
/// until the strict checkers land (#411, #412); and a year of 17 digits is within the range of the datatype layer, where the case expects a smaller
/// implementation-defined range.
/// </para>
/// <para>
/// Every XPath 2.0 case of the two sets that names one of these types is accounted for: it is in <see cref="Cases"/>, in <see cref="Excluded"/>, or in
/// <see cref="OutOfShape"/>, whose expression is not made of literals, constructors, and the operators above and has the reason beside it: a function
/// of a group that has not landed, a for expression, the context item, or a derived type (XP-23, #299).
/// </para>
/// </remarks>
internal static class Qt3RemainingCastSelection
